<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class AttendanceParticipant extends Model { protected $fillable=['attendance_event_id','uuid','participant_type','employee_id','name_snapshot','role_snapshot','department_snapshot','organization','email','expected','invitation_status','invited_at','added_after_freeze','excluded_at','exclusion_reason','excluded_by','credential_hash','credential_expires_at']; protected $casts=['expected'=>'boolean','invited_at'=>'datetime','added_after_freeze'=>'boolean','excluded_at'=>'datetime','credential_expires_at'=>'datetime']; public function event(){return$this->belongsTo(AttendanceEvent::class,'attendance_event_id');} public function employee(){return$this->belongsTo(Empleado::class);} public function record(){return$this->hasOne(AttendanceRecord::class);} }
